def natAbsDiff (a b : Nat) : Nat := (a - b) + (b - a)

@[simp] theorem natAbsDiff_self (a : Nat) : natAbsDiff a a = 0 := by
  unfold natAbsDiff; omega

theorem nfEquiv_trans {nf₁ nf₂ nf₃ : NormalForm}
    (h12 : nfEquiv nf₁ nf₂) (h23 : nfEquiv nf₂ nf₃) : nfEquiv nf₁ nf₃ :=
  ⟨h12.1.trans h23.1, seedAgree_trans h12.2 h23.2⟩

def TauIntQ.add : TauIntQ → TauIntQ → TauIntQ :=
  Quotient.lift₂ (fun a b => (a.add b).toQ)
    (fun a₁ b₁ a₂ b₂ ha hb => Quotient.sound (TauInt.add_respects_equiv a₁ a₂ b₁ b₂ ha hb))

def TauIntQ.mul : TauIntQ → TauIntQ → TauIntQ :=
  Quotient.lift₂ (fun a b => (a.mul b).toQ)
    (fun a₁ b₁ a₂ b₂ ha hb => Quotient.sound (TauInt.mul_respects_equiv a₁ a₂ b₁ b₂ ha hb))

def TauIntQ.neg : TauIntQ → TauIntQ :=
  Quotient.lift (fun a => a.negate.toQ)
    (fun a b h => Quotient.sound (TauInt.negate_respects_equiv a b h))

def TauIntQ.ofInt (n : Int) : TauIntQ :=
  if h : n ≥ 0 then (⟨n.toNat, 0⟩ : TauInt).toQ
  else (⟨0, (-n).toNat⟩ : TauInt).toQ

def TauRatQ.add : TauRatQ → TauRatQ → TauRatQ :=
  Quotient.lift₂ (fun a b => (a.add b).toQ)
    (fun a₁ b₁ a₂ b₂ ha hb => Quotient.sound (TauRat.add_respects_equiv a₁ a₂ b₁ b₂ ha hb))

def TauRatQ.mul : TauRatQ → TauRatQ → TauRatQ :=
  Quotient.lift₂ (fun a b => (a.mul b).toQ)
    (fun a₁ b₁ a₂ b₂ ha hb => Quotient.sound (TauRat.mul_respects_equiv a₁ a₂ b₁ b₂ ha hb))

def TauRatQ.neg : TauRatQ → TauRatQ :=
  Quotient.lift (fun a => a.negate.toQ)
    (fun a b h => Quotient.sound (TauRat.negate_respects_equiv a b h))

private theorem TauRatQ.lift_via_toRat (x y : TauRatQ)
    (h : x.toRat = y.toRat) : x = y :=
  (TauRatQ.eq_iff_toRat_eq x y).mpr h

theorem equiv_trans {a b c : CauchyTauReal}
    (hab : equiv a b) (hbc : equiv b c) : equiv a c :=
  TauReal.equiv_trans hab hbc

def TauRealQ.neg : TauRealQ → TauRealQ :=
  Quotient.lift (fun a => a.neg.toQ)
    (fun a b h => Quotient.sound (CauchyTauReal.neg_respects_equiv a b h))

def TauComplex.mul (a b : TauComplex) : TauComplex :=
  ⟨TauReal.sub (TauReal.mul a.re b.re) (TauReal.mul a.im b.im),
   TauReal.add (TauReal.mul a.re b.im) (TauReal.mul a.im b.re)⟩

def finiteStageEpsilon (n : Nat) : TauRat :=
  ((iotaApproxAt n).mul ((piApproxAt n).add (eApproxAt n))).sub
    (twoApproxAt n)

def galois_compose (σ τ_aut : GaloisAut) (_ : σ.stage = τ_aut.stage := by rfl) :
    GaloisAut :=
  { stage := σ.stage
  , multiplier := (σ.multiplier * τ_aut.multiplier) % primorial σ.stage }

def tau_integral (f : Nat → Int) (k : Nat) : TauIntegral :=
  { numerator := stage_sum f k
  , denominator := primorial k }

def both_channels_active (n N : TauIdx) : Bool :=
  let (b, c) := bc_ratio_pair n N
  b > 0 && c > 0

def b_minority_check (n N : TauIdx) : Bool :=
  let (b, c) := bc_ratio_pair n N
  b < c

def stage_measure (p : Nat → Bool) (k : Nat) : StageMeasure :=
  let pk := primorial k
  let count := count_satisfying p k
  { numerator := count
  , denominator := pk }

def measure_compatibility_check (tms : TowerMeasurableSet) (k : Nat) : Bool :=
  let pk := primorial k
  let pk1 := primorial (k + 1)
  let ck := count_satisfying (tms.predicate k) k
  let ck1 := count_satisfying (tms.predicate (k + 1)) (k + 1)
  ck1 * pk == ck * pk1

def TauRat.equiv (a b : TauRat) : Prop :=
  TauInt.equiv (a.num.mul (TauInt.fromNat b.den))
               (b.num.mul (TauInt.fromNat a.den))

theorem nat_to_taurat_injective {a b : TauIdx}
    (h : nat_to_taurat a = nat_to_taurat b) : a = b :=
  nat_to_tauint_injective (int_to_taurat_injective h)

def TauQuaternion.equiv (a b : TauQuaternion) : Prop :=
  TauReal.equiv a.w b.w ∧ TauReal.equiv a.x b.x ∧
  TauReal.equiv a.y b.y ∧ TauReal.equiv a.z b.z

private theorem taureal_const_bridge (a b : TauRat)
    (h : ∀ n : Nat, TauRat.equiv a b) : TauReal.equiv ⟨fun _ => a⟩ ⟨fun _ => b⟩ :=
  TauReal.equiv_of_pointwise (fun n => h n)

def refinementMwd :
    DefectInverseSystem.SigmaFixedThread refinementGrowingTorusSystem → Nat :=
  fun _ => 0

private theorem getD_eq_getElem (l : List TauIdx) (i : Nat) (d : TauIdx) (h : i < l.length) :
    l.getD i d = l[i] := by
  simp [List.getD, h]

def mk_omega_tail_neg (n d : TauIdx) : OmegaTail :=
  { depth := d
    components := omega_neg_list n d
    depth_eq := omega_neg_list_length n d }

def add_neg_check (n d : TauIdx) : Bool :=
  let neg_rep := (primorial d - n % primorial d) % primorial d
  (mk_omega_tail_add n neg_rep d).components == (mk_omega_zero d).components

def TauRat.inv (q : TauRat) (h : q.is_nonzero) : TauRat :=
  { num := if 0 < q.num.toInt then ⟨q.den, 0⟩ else ⟨0, q.den⟩,
    den := q.num.toInt.natAbs,
    den_pos := Int.natAbs_pos.mpr h }

private theorem TauRat.inv_num_toInt_pos (q : TauRat) :
    (⟨q.den, 0⟩ : TauInt).toInt = (q.den : Int) := by
  show (q.den : Int) - 0 = (q.den : Int); ring

private theorem TauRat.inv_num_toInt_neg (q : TauRat) :
    (⟨0, q.den⟩ : TauInt).toInt = -(q.den : Int) := by
  show (0 : Int) - q.den = -(q.den : Int); ring

theorem TauRat.lt_trans {a b c : TauRat}
    (hab : TauRat.lt a b) (hbc : TauRat.lt b c) : TauRat.lt a c :=
  _root_.lt_trans hab hbc

theorem TauRat.lt_asymm {a b : TauRat}
    (hab : TauRat.lt a b) : ¬ TauRat.lt b a :=
  fun hba => TauRat.lt_irrefl a (TauRat.lt_trans hab hba)

theorem TauRat.le_trans {a b c : TauRat}
    (hab : TauRat.le a b) (hbc : TauRat.le b c) : TauRat.le a c :=
  _root_.le_trans hab hbc

def TauReal.BoundedAwayFromZero (a : TauReal) : Prop :=
  ∃ k N : Nat, ∀ n : Nat, N ≤ n →
    TauRat.lt (TauRat.ofNatRecip k) (a.approx n).abs

def TauReal.inv (a : TauReal) : TauReal :=
  ⟨fun n => if h : (a.approx n).is_nonzero then TauRat.inv (a.approx n) h
            else TauRat.one⟩

def TauReal.lt (a b : TauReal) : Prop :=
  ∃ k N : Nat, ∀ n : Nat, N ≤ n →
    TauRat.lt ((a.approx n).add (TauRat.ofNatRecip k)) (b.approx n)

def TauReal.le (a b : TauReal) : Prop :=
  ∀ k : Nat, ∃ N : Nat, ∀ n : Nat, N ≤ n →
    TauRat.lt (a.approx n) ((b.approx n).add (TauRat.ofNatRecip k))

theorem TauReal.lt_asymm {a b : TauReal}
    (hab : TauReal.lt a b) : ¬ TauReal.lt b a :=
  fun hba => TauReal.lt_irrefl a (TauReal.lt_trans hab hba)

def torusMwd :
    DefectInverseSystem.SigmaFixedThread TorusDefectSystem → Nat :=
  fun _ => 0

theorem HolEndMorphismFull.preserves_crossingPoint
    {D : DefectInverseSystem}
    {anchor : ∀ n, D.defect_level n → Prop}
    {mwd : D.SigmaFixedThread → Nat}
    (f : HolEndMorphismFull D anchor mwd)
    (t : D.SigmaFixedThread)
    (h : DefectInverseSystem.IsCrossingPoint anchor mwd t) :
    DefectInverseSystem.IsCrossingPoint anchor mwd
      (f.toHolEndMorphism.actSigmaFixed t) :=
  ⟨f.preserves_NP t h.1, f.preserves_OA t h.2⟩

def windowSum (cf : List Nat) (width start : Nat) : Nat :=
  (List.range width).foldl (fun acc i =>
    acc + (cf.getD (start + i) 0)) 0

def occ_size (x : TauIdx) : TauIdx :=
  if x ≤ 1 then 1
  else occ_size_go x x

def dim_tau_check : Bool :=
  dim_tau_witnesses.all fun (x, a, b, c, d) =>
    coord_A x == a && coord_B x == b && coord_C x == c && coord_D x == d

private def is_prime_cb (n : Nat) : Bool :=
  if n < 2 then false
  else go 2 (n + 1)
where
  go (d fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if d * d > n then true
    else if n % d == 0 then false
    else go (d + 1) (fuel - 1)
  termination_by fuel

def verify_descent_up_to_go (i n : Nat) (fuel : Nat) : Bool :=
  if fuel = 0 then true
  else if i > n then true
  else full_descent_check i && verify_descent_up_to_go (i + 1) n (fuel - 1)
termination_by fuel

