def NFStep.ofPeel (x : TauIdx) : NFStep :=
  let (a, b, c, d) := greedy_peel x
  { A := a, B := b, C := c, D := d }

def prime_count_go (n i acc : TauIdx) (fuel : Nat) : TauIdx :=
  if fuel = 0 then acc
  else if i > n then acc
  else if is_prime_bool i then prime_count_go n (i + 1) (acc + 1) (fuel - 1)
  else prime_count_go n (i + 1) acc (fuel - 1)
termination_by fuel

def nthPrime_go (target : TauIdx) (candidate count : TauIdx) (fuel : Nat) : TauIdx :=
  if fuel = 0 then candidate
  else if is_prime_bool candidate then
    if count == target then candidate
    else nthPrime_go target (candidate + 1) (count + 1) (fuel - 1)
  else nthPrime_go target (candidate + 1) count (fuel - 1)
termination_by fuel

def prime_index (p : TauIdx) : TauIdx :=
  if p ≤ 2 then 0
  else prime_count (p - 1)

def greedy_peel (x : TauIdx) : TauIdx × TauIdx × TauIdx × TauIdx :=
  if x ≤ 1 then (1, 0, 0, x)
  else
    let a := largest_prime_divisor x
    let v := p_adic_val a x
    let c := max_tet_div a v
    let b := v / (tetration a (c - 1))
    let t := tower_atom a b c
    let d := x / t
    (a, b, c, d)

def execNF (nf : NormalForm) (x : TauObj) : TauObj :=
  let mapped := ⟨nf.seedMap x.seed, x.depth⟩
  Tau.Orbit.iter_rho nf.rhoCount mapped

def sigma_conjugate_transformer (sigma_X sigma_Y f : StageFun) :
    StageFun :=
  StageFun.comp sigma_Y (StageFun.comp f sigma_X)

def restriction (f : StageFun) (inK : TauIdx → Bool) : StageFun :=
  { b_fun := fun n k => if inK n then 0 else f.b_fun n k
    c_fun := fun n k => if inK n then 0 else f.c_fun n k }

def TowerCoherent (f : StageFun) : Prop :=
  (∀ n k l : TauIdx, k ≤ l → reduce (f.b_fun n l) k = f.b_fun n k) ∧
  (∀ n k l : TauIdx, k ≤ l → reduce (f.c_fun n l) k = f.c_fun n k)

private theorem reduce_compat (n : TauIdx) {k l : TauIdx} (h : k ≤ l) :
    reduce (reduce n l) k = reduce n k :=
  reduction_compat n h

def StageFun.comp (f₁ f₂ : StageFun) : StageFun :=
  ⟨fun n k => f₁.b_fun (f₂.b_fun n k) k,
   fun n k => f₁.c_fun (f₂.c_fun n k) k⟩

def Truth4.toSectorPair : Truth4 -> Tau.Polarity.SectorPair
  | T => { b_sector := 1, c_sector := 1 }
  | F => { b_sector := 0, c_sector := 0 }
  | B => Tau.Polarity.e_plus_sector
  | N => Tau.Polarity.e_minus_sector

def orthodox_resonance : OrthodoxFoundation → DiagonalResonance
  | .ZFC  => { contraction_present := true, equality_congruence := true, self_products := true }
  | .CIC  => { contraction_present := true, equality_congruence := true, self_products := true }
  | .HoTT => { contraction_present := true, equality_congruence := true, self_products := true }

def GaussInt.mul (a b : GaussInt) : GaussInt :=
  ⟨a.re * b.re - a.im * b.im, a.re * b.im + a.im * b.re⟩

@[ext]

def mod_inv_go (a m x fuel : Nat) : Nat :=
  if fuel = 0 then 0
  else if (a * x) % m == 1 then x
  else mod_inv_go a m (x + 1) (fuel - 1)
termination_by fuel

def crt_basis (k i : TauIdx) : TauIdx :=
  let mk := primorial k
  let pi := nth_prime (i + 1)
  let cofactor := mk / pi
  (cofactor * mod_inv cofactor pi) % mk

def crt_coherence_check (x k l : TauIdx) : Bool :=
  k ≤ l && (crt_reconstruct (crt_decompose x l) l % primorial k ==
            crt_reconstruct (crt_decompose x k) k)

def crt_exhaustive_check_go (k x : TauIdx) (fuel : Nat) : Bool :=
  if fuel = 0 then true
  else if x ≥ primorial k then true
  else crt_roundtrip_check x k && crt_exhaustive_check_go k (x + 1) (fuel - 1)
termination_by fuel

def crt_partition_go (k : TauIdx) (i fuel : Nat) (acc : TauIdx) : TauIdx :=
  if fuel = 0 then acc
  else if i ≥ k then acc
  else crt_partition_go k (i + 1) (fuel - 1) ((acc + crt_basis k i) % primorial k)
termination_by fuel

def ext_gcd (a b : Nat) : Nat × Int × Int :=
  if b = 0 then (a, 1, 0)
  else
    let r := ext_gcd b (a % b)
    (r.1, r.2.2, r.2.1 - ↑(a / b) * r.2.2)
termination_by b
decreasing_by exact Nat.mod_lt a (by omega)

private theorem getD_eq_getElem' (l : List TauIdx) (i : Nat) (d : TauIdx)
    (h : i < l.length) : l.getD i d = l[i] := by
  simp [List.getD, h]

def OmegaInverseLimit.truncate (t : OmegaInverseLimit) (d : TauIdx)
    : OmegaTail :=
  ⟨d, coeff_list t.coeff d, coeff_list_length t.coeff d⟩

def nth_prime (k : TauIdx) : TauIdx :=
  if k = 0 then 0
  else nth_prime_go k 0 1 (k * k * 10 + 10)

def reduction_compat_check (x k l : TauIdx) : Bool :=
  if k ≤ l then reduce (reduce x l) k == reduce x k
  else true

private theorem count_primes_in_unfold (lo hi : Nat) :
    count_primes_in lo hi =
    if lo ≥ hi then 0
    else (if is_prime_bool (lo + 1) then 1 else 0) + count_primes_in (lo + 1) hi :=
  count_primes_in.eq_1 lo hi

def nat_to_tail_go (n k d : Nat) (fuel : Nat) (acc : List TauIdx) : List TauIdx :=
  if fuel = 0 then acc
  else if k > d then acc
  else nat_to_tail_go n (k + 1) d (fuel - 1) (acc ++ [reduce n k])
termination_by fuel

def nat_to_tail (n d : TauIdx) : OmegaTail :=
  let comps := nat_to_tail_components n d
  ⟨comps.length, comps, rfl⟩

def compat_outer (comps : List TauIdx) (d k : TauIdx) (fuel : Nat) : Bool :=
  if fuel = 0 then true
  else if k > d then true
  else compat_inner comps k d d && compat_outer comps d (k + 1) (fuel - 1)
termination_by fuel

def Compatible (t : OmegaTail) : Prop :=
  ∀ k l, 1 ≤ k → k ≤ l → l ≤ t.depth →
    t.components.getD (l - 1) 0 % primorial k = t.components.getD (k - 1) 0

private theorem getD_eq_getElem (l : List TauIdx) (i : Nat) (d : TauIdx) (h : i < l.length) :
    l.getD i d = l[i] := by
  simp [List.getD, h]

def tail_equiv (t1 t2 : OmegaTail) : Bool :=
  let d := min t1.depth t2.depth
  equiv_go t1.components t2.components d 0 d

def divergence_depth (t1 t2 : OmegaTail) : TauIdx :=
  let d := min t1.depth t2.depth
  diverge_go t1.components t2.components d 0 d

private theorem getD_eq_getElem (l : List TauIdx) (i : Nat) (d : TauIdx) (h : i < l.length) :
    l.getD i d = l[i] := by
  simp [List.getD, h]

def large_prime_batch_go (lo hi N : Nat) (fuel : Nat) : Bool :=
  if fuel = 0 then true
  else if lo > hi then true
  else large_prime_c_bounded lo N && large_prime_batch_go (lo + 1) hi N (fuel - 1)
termination_by fuel

def cofinal_check_go (f : Nat → Nat) (i to_depth : Nat) (fuel : Nat) : Bool :=
  if fuel = 0 then false
  else if i > to_depth then false
  else if f i ≠ 0 then true
  else cofinal_check_go f (i + 1) to_depth (fuel - 1)
termination_by fuel

def b_polarized_check (p d : TauIdx) : Bool :=
  if d ≤ 2 then false
  else const_check (c_channel_seq p) 2 d && cofinal_check (b_channel_seq p) 1 d

def c_polarized_check (p d : TauIdx) : Bool :=
  if d ≤ 2 then false
  else const_check (b_channel_seq p) 2 d && cofinal_check (c_channel_seq p) 1 d

def teich_decomp_check (n d : TauIdx) : Bool :=
  let zero_list := (List.range d).map (fun _ => 0)
  let sum := teich_decomp_check_go n d 0 d zero_list
  let target := (mk_omega_tail n d).components
  sum == target

private theorem strict_mem_sub_lt {a b : TauIdx} (hb : b ≠ 0) (h : tau_strict_mem a b) :
    a < b :=
  tau_strict_mem_lt h hb

private theorem strict_mem_nz_sub_lt {a b : TauIdx} (h : tau_strict_mem_nz a b) :
    a < b :=
  tau_strict_mem_lt h.1 h.2

def GermConvergence (seq : Nat -> TauIdx) (d : Nat) : Prop :=
  exists N, forall i j, i ≥ N -> j ≥ N ->
    forall k, k < d -> reduce (seq i) (k + 1) = reduce (seq j) (k + 1)

def EventuallyConst (Φ : Truth4 → Truth4) (s : Truth4) (v : Truth4) :
    Prop :=
  ∃ n0 : Nat, ∀ n, n0 ≤ n → cauchyIter Φ n s = v

def TauArrow.ext_agree (a₁ a₂ : TauArrow)
    (hs : a₁.source = a₂.source) (ht : a₁.target = a₂.target) :
    a₁.source = a₂.source ∧ a₁.target = a₂.target := ⟨hs, ht⟩

def characteristic_morphism (b_member c_member : TauIdx → Bool) :
    TauIdx → Omega_tau :=
  fun x => Truth4.fromBoolPair (b_member x, c_member x)

def Entails (a b : Truth4) : Prop :=
  IsDesignated a → IsDesignated b

@[simp] theorem entails_refl (a : Truth4) : Entails a a := fun h => h

def canonical_character : IdempotentCharacter :=
  { b_ch := fun x k => (from_tau_idx (reduce x k)).b
  , c_ch := fun x k => (from_tau_idx (reduce x k)).c }

def chi_plus_character : IdempotentCharacter :=
  { b_ch := fun x k => (reduce x k : Int)
  , c_ch := fun _ _ => 0 }

def chi_minus_character : IdempotentCharacter :=
  { b_ch := fun _ _ => 0
  , c_ch := fun x k => (reduce x k : Int) }

def IdempotentCharacter.add (chi1 chi2 : IdempotentCharacter) : IdempotentCharacter :=
  { b_ch := fun x k => chi1.b_ch x k + chi2.b_ch x k
  , c_ch := fun x k => chi1.c_ch x k + chi2.c_ch x k }

def IdempotentCharacter.mul (chi1 chi2 : IdempotentCharacter) : IdempotentCharacter :=
  { b_ch := fun x k => chi1.b_ch x k * chi2.b_ch x k
  , c_ch := fun x k => chi1.c_ch x k * chi2.c_ch x k }

def full_central_theorem_check (db bound : TauIdx) : Bool :=
  central_theorem_check db bound &&
  holographic_check db bound

def bndlift_stagefun : StageFun :=
  { b_fun := fun x k => (from_tau_idx (bndlift x k)).b
  , c_fun := fun x k => (from_tau_idx (bndlift x k)).c }

def extension_sector_roundtrip_check (bound db : TauIdx) : Bool :=
  go 2 1 ((bound + 1) * (db + 1))
where
  go (x k fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if x > bound then true
    else if k >= db then go (x + 1) 1 (fuel - 1)
    else
      -- Code the B and C functions separately
      let b_fn : TauIdx -> Int := fun n => (bndlift_stagefun.b_fun n k : Int)
      let c_fn : TauIdx -> Int := fun n => (bndlift_stagefun.c_fun n k : Int)
      let coded_b := code_extract b_fn (k + 1) x
      let coded_c := code_extract c_fn (k + 1) x
      -- Should match the direct evaluation at reduce(x, k+1)
      let direct_b := (bndlift_stagefun.b_fun (reduce x (k + 1)) k : Int)
      let direct_c := (bndlift_stagefun.c_fun (reduce x (k + 1)) k : Int)
      let ok := coded_b == direct_b && coded_c == direct_c
      ok && go x (k + 1) (fuel - 1)
  termination_by fuel

def code_decode_uniqueness_check (bound db : TauIdx) : Bool :=
  go 2 1 ((bound + 1) * (db + 1))
where
  go (x k fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if x > bound then true
    else if k >= db then go (x + 1) 1 (fuel - 1)
    else
      -- The bndlift "function" at stage k
      let bndlift_fn : TauIdx -> Int := fun n => (bndlift n k : Int)
      -- code_extract should give bndlift(reduce(x, k+1), k) = reduce(reduce(x, k+1), k+1)
      -- = reduce(x, k+1) = bndlift(x, k) for x < P_{k+1}
      let coded := code_extract bndlift_fn (k + 1) x
      let direct := (bndlift (reduce x (k + 1)) k : Int)
      (coded == direct) && go x (k + 1) (fuel - 1)
  termination_by fuel

#eval let py := preyoneda_embed_nat (fun n => n) 7 2
      let fn : TauIdx -> Int := fun n => (preyoneda_embed_nat (fun m => m) n 2 : Int)
      (py, code_extract fn 2 7)  -- (1, 1): same value

def is_proto_rational (x max_k : TauIdx) : Bool :=
  if x ≤ 1 then false
  else find_stage x 1 (max_k + 1)
where
  find_stage (x k fuel : Nat) : Bool :=
    if fuel = 0 then false
    else if k > max_k then false
    else if reduce x k == x then true
    else find_stage x (k + 1) (fuel - 1)
  termination_by fuel

def proto_rational_stage (x max_k : TauIdx) : TauIdx :=
  if x ≤ 1 then 0
  else find_min_stage x 1 (max_k + 1)
where
  find_min_stage (x k fuel : Nat) : Nat :=
    if fuel = 0 then 0
    else if k > max_k then 0
    else if reduce x k == x then k
    else find_min_stage x (k + 1) (fuel - 1)
  termination_by fuel

def proto_rational_count_check : Bool :=
  proto_rational_count_at_stage 2 == 4 &&    -- x = 2, 3, 4, 5
  proto_rational_count_at_stage 3 >= 10       -- many new at stage 3

