  geometric_bisquare_check db bound &&
  full_export_check db bound k_max

def scaling_chain_check : Bool :=
  scaling_level_index .E0_algebraic < scaling_level_index .E1_geometric &&
  scaling_level_index .E1_geometric < scaling_level_index .E2_enriched

def d_squared_zero_tower_check (db bound : TauIdx) : Bool :=
  go 1 0 ((db + 1) * (bound + 1))
where
  go (k x fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if k > db then true
    else if x > bound then go (k + 1) 0 (fuel - 1)
    else
      let f_reduce : TauIdx -> TauIdx -> Int := fun y stage => (reduce y stage : Int)
      let pk := primorial k
      if pk == 0 then go k (x + 1) (fuel - 1)
      else
        let df_sum := sum_exterior_deriv f_reduce k 0 pk (pk + 1)
        (df_sum == 0) && go k (x + 1) (fuel - 1)
  termination_by fuel

def tau_manifold_check (db bound : TauIdx) : Bool :=
  let m := compute_tau_manifold db bound
  m.has_atlas && m.has_transitions && m.has_d_squared_zero

def e0_check_id_compat (k x fuel : Nat) : Bool :=
  if fuel = 0 then true
  else if k = 0 then true
  else if x >= primorial k then true
  else
    let id_val := reduce x k
    let reduced_id := reduce id_val (k - 1)
    let direct := reduce x (k - 1)
    (reduced_id == direct) && e0_check_id_compat k (x + 1) (fuel - 1)
termination_by fuel

def primorial_chain : ChainComplex :=
  { max_degree := 5
  , boundary := fun n x => if n == 0 then 0 else reduce x (n - 1) }

def homology_trivial_check (k : Nat) : Bool :=
  if k == 0 then true
  else
