where
  go (x fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if x > bound then true
    else
      let tc_ok := twocat_id_tower_scan x 1 db (db * db + db + 1)
      let vc_ok := twocat_vert_comp_scan x 1 db (db + 1)
      let hc_ok := twocat_horiz_comp_scan x 1 db (db + 1)
      tc_ok && vc_ok && hc_ok && go (x + 1) (fuel - 1)
  termination_by fuel

