  (interior_bipolar p).c_sector

def between_transitivity_check (bound db : TauIdx) : Bool :=
  go 2 2 2 2 ((bound + 1) * (bound + 1) * (bound + 1) * (bound + 1))
where
  go (x y z w fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if x > bound then true
    else if y > bound then go (x + 1) 2 2 2 (fuel - 1)
    else if z > bound then go x (y + 1) 2 2 (fuel - 1)
    else if w > bound then go x y (z + 1) 2 (fuel - 1)
    else
      let ok := !(between x y z db && between x z w db) || between x y w db
      ok && go x y z (w + 1) (fuel - 1)
  termination_by fuel

def cong_reflexivity_check (bound db : TauIdx) : Bool :=
  go 2 2 ((bound + 1) * (bound + 1))
where
  go (a b fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if a > bound then true
    else if b > bound then go (a + 1) 2 (fuel - 1)
    else congruent a b b a db && go a (b + 1) (fuel - 1)
  termination_by fuel

def den_cong_compat_check (db : TauIdx) : Bool :=
  let quads := [(2,3,4,5), (3,5,7,9), (2,4,6,8), (5,7,3,11),
                (2,6,4,12), (3,9,5,15), (7,11,2,8)]
  quads.all fun (a, b, c, d) =>
    !congruent a b c d db || cong_compat_stages a b c d db

def pasch_exhaustive_check (bound db : TauIdx) : Bool :=
  go 2 2 2 ((bound + 1) * (bound + 1) * (bound + 1))
where
  go (a b c fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if a > bound then true
    else if b > bound then go (a + 1) 2 2 (fuel - 1)
    else if c > bound then go a (b + 1) 2 (fuel - 1)
    else collinear_triple a b c db && go a b (c + 1) (fuel - 1)
  termination_by fuel

def on_depth_line (x y z db : TauIdx) : Bool :=
  let k := disagree_depth x y db
  disagree_depth x z db == k || disagree_depth y z db == k

def parallel_check_y (x bound db : TauIdx) : Bool :=
  go 2 (bound + 1)
where
  go (y fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if y > bound then true
    else if x == y then go (y + 1) (fuel - 1)
    else parallel_check_z x y bound db && go (y + 1) (fuel - 1)
  termination_by fuel

def crt_decompose (x stage : TauIdx) : TauIdx × TauIdx :=
  let pn := primorial stage
  let p_next := nth_prime (stage + 1)
  (x % pn, x % p_next)

def crt_unique_check (stage : TauIdx) : Bool :=
  let pn1 := primorial (stage + 1)
  if pn1 <= 1 then true
  else go 0 0 (pn1 * pn1)
where
  go (x y fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if x >= primorial (stage + 1) then true
    else if y >= primorial (stage + 1) then go (x + 1) (x + 2) (fuel - 1)
    else if x == y then go x (y + 1) (fuel - 1)
    else
      let dx := crt_decompose x stage
      let dy := crt_decompose y stage
      (dx != dy) && go x (y + 1) (fuel - 1)
  termination_by fuel

