  SplitComplex.mul SplitComplex.j SplitComplex.j == SplitComplex.one

def idempotency_check : Bool :=
  SectorPair.mul e_plus_sector e_plus_sector == e_plus_sector &&
  SectorPair.mul e_minus_sector e_minus_sector == e_minus_sector

def basis_orthogonality_check (k_max bound : TauIdx) : Bool :=
  go 1 1 0 0 ((k_max + 1) * (k_max + 1) * (bound + 1))
where
  go (k pi_idx v w fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if k > k_max then true
    else
      let p := nth_prime pi_idx
      if pi_idx > k then go (k + 1) 1 0 0 (fuel - 1)
      else if p == 0 then go k (pi_idx + 1) 0 0 (fuel - 1)
      else if v >= p then go k (pi_idx + 1) 0 0 (fuel - 1)
      else if w >= p then go k pi_idx (v + 1) 0 (fuel - 1)
      else if v == w then go k pi_idx v (w + 1) (fuel - 1)
      else
        ortho_pair k pi_idx v w && go k pi_idx v (w + 1) (fuel - 1)
  termination_by fuel

def hol_comp (f g : TauIdx -> TauIdx -> TauIdx)
    (n k : TauIdx) : TauIdx :=
  f (g n k) k

def mk_holend (max_stage max_val : TauIdx) : HolEndCat :=
  { max_stage := max_stage
  , max_val := max_val
  }

def l2_inner_product (f g : Nat → Int) (k : Nat) : L2Inner :=
  { numerator := inner_product_sum f g k
  , denominator := primorial k }

def norm_definiteness_check (k : Nat) : Bool :=
  let zero_fn : Nat → Int := fun _ => 0
  l2_norm_sq zero_fn k == 0

def l2_completeness_check (k : Nat) : Bool :=
  let pk := primorial k
  let pk1 := primorial (k + 1)
  -- Check: inner product at stage k of reduced functions equals
  -- inner product at stage k+1 after appropriate normalization
  let f : Nat → Int := fun x => (x : Int)
  let g : Nat → Int := fun x => (x * x : Int)
  -- The reduced inner product: Σ_{x in Z/M_k} f(x)g(x)
  let ip_k := inner_product_sum f g k
  -- At stage k+1, the same functions restricted to Z/M_{k+1}
  let ip_k1 := inner_product_sum f g (k + 1)
  -- Normalization: ip_k / M_k should relate to ip_{k+1} / M_{k+1}
  -- Check: ip_k * M_{k+1} and ip_{k+1} * M_k have consistent sign
  let ratio_ok := (ip_k * pk1 > 0) == (ip_k1 * pk > 0) || ip_k == 0
  -- Dimension check: dim(L²(Z/M_k)) = M_k
  let dim_ok := pk > 0
  ratio_ok && dim_ok

def laurent_coeff (x k prime_idx : TauIdx) : TauIdx :=
  if prime_idx == 0 || prime_idx > k then 0
  else x % nth_prime prime_idx

def tau_residue (x i : TauIdx) : TauIdx :=
