  iota > 335000 && iota < 350000

def wave_vs_laplace_check : Bool :=
  -- Split-complex sector product: componentwise
  let sp1 : SectorPair := to_sectors ⟨2, 3⟩  -- (5, -1)
  let sp2 : SectorPair := to_sectors ⟨1, 4⟩  -- (5, -3)
  let sp_prod := SectorPair.mul sp1 sp2       -- (25, 3)
  -- Verify it equals to_sectors of the split-complex product
  let sc_prod := SplitComplex.mul ⟨2, 3⟩ ⟨1, 4⟩  -- (2*1+3*4, 2*4+3*1) = (14, 11)
  sp_prod == to_sectors sc_prod

def alpha_ray_member (x a : TauIdx) : Bool :=
  let p := from_tau_idx x
  p.a == a && p.b == 1 && p.c == 1

def leibniz_pi_scaled (terms scale : Nat) : Nat :=
  let (pos, neg) := go 0 (terms + 1) 0 0
  if pos >= neg then pos - neg else 0
where
  go (k fuel pos neg : Nat) : Nat × Nat :=
    if fuel = 0 then (pos, neg)
    else if k >= terms then (pos, neg)
    else
      let denom := 2 * k + 1
      let term := 4 * scale / denom
      if k % 2 == 0 then go (k + 1) (fuel - 1) (pos + term) neg
      else go (k + 1) (fuel - 1) pos (neg + term)
  termination_by fuel

def pi_convergence_check : Bool :=
  let pi_approx := pi_scaled 1000
  pi_approx > 3100000 && pi_approx < 3200000

private def is_prime_arith (n : Nat) : Bool :=
  if n < 2 then false
  else go 2 (n + 1)
where
  go (d fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if d * d > n then true
    else if n % d == 0 then false
    else go (d + 1) (fuel - 1)
  termination_by fuel

def is_squarefree (n : Nat) : Bool :=
  if n <= 1 then true
  else go 2 (n + 1)
where
  go (d fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if d * d > n then true
    else if n % (d * d) == 0 then false
    else go (d + 1) (fuel - 1)
  termination_by fuel

def conjectural_properly_marked : Bool :=
