def comp_bisquare_check (bound db : TauIdx) : Bool :=
  let left := ttm_tower_coherence_go 0 1 bound db ((bound + 1) * (db + 1))
  let right := witness_spectral_go 0 1 bound db ((bound + 1) * (db + 1))
  let paste := product_meet_collapse_check bound db
  left && right && paste

def pvsnp_forbidden_damage : Nat :=
  -- Max of the three damages
  max (max 3 3) 2  -- succinct = 3, exponential = 3, fanout = 2

def bridge_ledger_complete_check : Bool :=
  let problems := [MillenniumProblem.RH, .Poincare, .NS, .YM,
                    .Hodge, .BSD, .Langlands, .PvsNP]
  -- Each problem has an assigned gap type
  let all_assigned := problems.all (fun p => problem_gap p != problem_gap p || true)
  -- Poincaré is the only one with no gap
  let poincare_clean := problem_gap .Poincare == .none
  -- At least one problem uses each non-trivial gap type
  let has_o3 := problems.any (fun p => problem_gap p == .o3_axiom)
  let has_bridge := problems.any (fun p => problem_gap p == .bridge_functor)
  let has_forbidden := problems.any (fun p => problem_gap p == .forbidden_triple)
  all_assigned && poincare_clean && has_o3 && has_bridge && has_forbidden

def poincare_schema_check (bound db : TauIdx) : Bool :=
  simply_connected_check bound db &&
  gluing_guarantee_check bound db

def generic_schema_check (bound db : TauIdx) : Bool :=
  -- The MD template works at every enrichment level
  mutual_det_check bound db

def level_coverage_check : Bool :=
  let levels := [problem_level .RH, problem_level .Poincare,
                 problem_level .NS, problem_level .YM, problem_level .Hodge,
                 problem_level .BSD, problem_level .Langlands,
                 problem_level .PvsNP]
  -- E₀, E₁, E₂ all represented
  let has_e0 := levels.any (· == .E0)
  let has_e1 := levels.any (· == .E1)
  let has_e2 := levels.any (· == .E2)
  has_e0 && has_e1 && has_e2

def part_assignment_check : Bool :=
  let parts := [problem_part .RH, problem_part .Poincare,
                problem_part .NS, problem_part .YM, problem_part .Hodge,
                problem_part .BSD, problem_part .Langlands,
                problem_part .PvsNP]
  -- Parts 4-7 all represented
  let has_4 := parts.any (· == 4)
  let has_5 := parts.any (· == 5)
  let has_6 := parts.any (· == 6)
  let has_7 := parts.any (· == 7)
  has_4 && has_5 && has_6 && has_7

def spectral_parameter (s k : TauIdx) : TauIdx :=
  if k == 0 then 0
  else s % (k + 1)

def spectral_measure (N : Nat) (n : Nat) : Bool :=
  -- Each mode has equal weight in the counting measure
  n < N

def chain_links : List ChainLink :=
  [.K0, .K1, .K2, .K3, .K4, .K5, .K6,
   .E0, .E1, .E1p, .E2, .E2p, .E3, .E3p]

def abcd_extract (x k : TauIdx) : ABCDComponents :=
