    if fuel = 0 then (m_acc, n_acc)
    else if m > bound then (m_acc, n_acc)
    else if n > bound then go (m + 1) 0 m_acc n_acc (fuel - 1)
    else
      let χ : BoundaryCharacter := ⟨Int.ofNat m, Int.ofNat n⟩
      let (m_acc', n_acc') := if sector_of χ == sec then
        (m_acc + m, n_acc + n)
      else (m_acc, n_acc)
      go m (n + 1) m_acc' n_acc' (fuel - 1)
  termination_by fuel

def is_prime_nat (n : Nat) : Bool :=
  if n < 2 then false
  else go 2 (n + 1)
where
  go (d fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if d * d > n then true
    else if n % d == 0 then false
    else go (d + 1) (fuel - 1)
  termination_by fuel

def goldbach_pair (n : Nat) : Bool :=
  if n < 4 || n % 2 != 0 then false
  else go 2 (n / 2 + 1)
where
  go (p fuel : Nat) : Bool :=
    if fuel = 0 then false
    else if p > n / 2 then false
    else if is_prime_nat p && is_prime_nat (n - p) then true
    else go (p + 1) (fuel - 1)
  termination_by fuel

