  else go 2 (n + 1)
where
  go (d fuel : Nat) : Bool :=
    if fuel = 0 then true
    else if d * d > n then true
    else if n % d == 0 then false
    else go (d + 1) (fuel - 1)
  termination_by fuel

def hl_twin_constant_approx (k : Nat) : Nat × Nat :=
  go 2 1 1 (k + 1)
where
  go (i num den fuel : Nat) : Nat × Nat :=
    if fuel = 0 then (num, den)
    else if i > k then (num, den)
    else
      let p := nth_prime i
      if p < 3 then go (i + 1) num den (fuel - 1)
      else
        let num' := num * (p * (p - 2))
        let den' := den * ((p - 1) * (p - 1))
        go (i + 1) num' den' (fuel - 1)
  termination_by fuel

